const body = $input.first().json.body || $input.first().json;
const event = body.triggerEvent || 'BOOKING_CREATED';
const payload = body.payload || body;
const attendee = (payload.attendees || [])[0] || {};
const responses = payload.responses || payload.bookingFieldsResponses || {};

function normalizeKey(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function getVal(key) {
  const expectedKey = normalizeKey(key);
  const responseKey = Object.keys(responses).find(candidate => normalizeKey(candidate) === expectedKey);
  if (!responseKey) return null;
  const field = responses[responseKey];
  if (typeof field === 'object' && field.value !== undefined) return field.value;
  return field;
}

const typeRaw = getVal('tipo_de_cita') || getVal('appointment_type') || 'otro';
const typeMap = {
  'valoracion inicial': 'valoracion_inicial', 'valoracion': 'valoracion_inicial',
  'limpieza': 'limpieza', 'ortodoncia': 'ortodoncia',
  'implante': 'implante', 'implantes': 'implante',
  'diseno de sonrisa': 'diseno_sonrisa', 'diseño de sonrisa': 'diseno_sonrisa',
  'urgencia': 'urgencia', 'urgencia dental': 'urgencia', 'otro': 'otro'
};
const appointmentType = typeMap[(typeRaw || '').toLowerCase()] || 'otro';

const firstVisitRaw = getVal('primera_visita') || getVal('is_first_visit');
const isFirstVisit = firstVisitRaw === null ? true
  : ['sí', 'si', 'yes', 'true', '1'].includes(String(firstVisitRaw).toLowerCase());

return [{ json: {
  triggerEvent: event,
  calBookingId: String(payload.uid || payload.id || ''),
  calEventTypeId: payload.eventTypeId || null,
  startTime: payload.startTime || payload.start_time,
  endTime: payload.endTime || payload.end_time,
  patientName: getVal('nombre_del_paciente') || attendee.name || getVal('name') || '',
  patientEmail: attendee.email || getVal('email') || '',
  patientPhone: attendee.phoneNumber || getVal('phone') || '',
  appointmentType,
  isFirstVisit,
  reasonForVisit: getVal('motivo_de_consulta') || getVal('notes') || null,
  status: event === 'BOOKING_CANCELLED' ? 'CANCELLED' : event === 'BOOKING_RESCHEDULED' ? 'RESCHEDULED' : 'ACCEPTED'
}}];
